import { Table, BooleanColumn, VersionColumn, StringColumn, SystemClassNameColumn, ReferenceColumn } from '../../db'

export const sys_package = Table({
    attributes: {
        'all_tables.text_index_translations': true,
        metadata_link_exempt: true,
    },
    audit: true,
    display: 'name',
    extensible: true,
    label: 'Package',
    name: 'sys_package',
    schema: {
        trackable: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Track user activity/usage on this package',
                    label: 'Trackable',
                    plural: 'Trackables',
                },
            ],
        }),
        version: VersionColumn({
            label: [
                {
                    hint: 'Identifies the latest version of the package in dot-decimal notation',
                    label: 'Version',
                    plural: 'Versions',
                },
            ],
        }),

        name: StringColumn({
            attributes: {
                ts_weight: '50',
            },
            label: [
                {
                    hint: 'The display field for the package',
                    label: 'Name',
                    plural: 'Names',
                },
            ],
            mandatory: true,
            maxLength: 100,
        }),
        license_model: StringColumn({
            default: 'none',
            choices: {
                none: {
                    label: 'Not applicable',
                    sequence: 1,
                },
                fulfiller: {
                    label: 'Fulfiller/Requester',
                    sequence: 2,
                },
                producer: {
                    label: 'Producer',
                    sequence: 3,
                },
                capacity: {
                    label: 'Capacity',
                    sequence: 4,
                },
                mixed: {
                    label: 'Mixed',
                    sequence: 5,
                },
                app_use: {
                    label: 'Application in use',
                    sequence: 6,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Subscription Model',
        }),

        sys_class_name: SystemClassNameColumn({
            default: 'javascript:current.getTableName();',
            dropdown: 'dropdown_without_none',
            label: 'Class',
            maxLength: 80,
        }),
        enforce_license: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
                edge_encryption_excluded: true,
            },
            default: 'none',
            choices: {
                none: {
                    label: 'None',
                    sequence: 1,
                },
                log: {
                    label: 'Monitor',
                    sequence: 2,
                },
                enforce: {
                    label: 'Required',
                    sequence: 3,
                },
            },
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Subscription requirement for usage of this package',
                    label: 'Subscription requirement',
                    plural: 'Subscription requirements',
                },
            ],
        }),
        license_category: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
                edge_encryption_excluded: true,
            },
            default: 'none',
            choices: {
                none: {
                    label: 'Not applicable',
                    sequence: 1,
                },
                general: {
                    label: 'General',
                    sequence: 2,
                },
                beta: {
                    label: 'Beta',
                    sequence: 3,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Subscription Category',
        }),
        licensable: BooleanColumn({
            label: [
                {
                    hint: 'Marks this package as licensable',
                    label: 'Licensable',
                    plural: 'Licensable',
                },
            ],
        }),
        source: StringColumn({
            default: `javascript:_getID();\r
\r
function _getID() {\r
  var source = current.getValue('source');\r
  var sys_id = current.getValue('sys_id');\r
  var scope = current.getValue('scope');\r
  return gs.nil(scope) || scope == 'global' ? source||sys_id : source||scope;\r
}`,
            label: 'ID',
            maxLength: 100,
        }),

        ide_created: StringColumn({
            label: [
                {
                    hint: 'Key to indicate which IDE was used to create the package',
                    label: 'IDE Created',
                    plural: 'IDE Created',
                },
            ],
            maxLength: 10,
        }),
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Package in use?',
                    label: 'Active',
                    plural: 'Active',
                },
            ],
        }),

        package_resolver_version: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default: '1.0.0',
            label: 'Package Resolver Version',
            maxLength: 255,
        }),
        package_json: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Package JSON',
            maxLength: 255,
            referenceTable: 'sys_module',
            referenceKey: 'path',
            referenceQual: 'pathENDSWITHpackage.json^EQ',
            useReferenceQualifier: 'simple',
        }),
    },
    textIndex: true,
})
